    static void firstTurns(){var m=game("BOTH",true);for(UUID owner:List.of(A,B)){UUID source=active(m,owner);check(!m.canUseAbility(owner,source,ABILITY),"First own turn offered Spiteful Evolution");atomic(m,()->m.useAbility(owner,source,ABILITY));check(!m.canEvolve(owner,source,TREE),"Normal evolution on first own turn");m.endTurn(owner);}ability(m,A,active(m,A));check(m.activePokemonView(A).damage()==20,"Second own turn Ability denied or counters absent");m.endTurn(A);ability(m,B,active(m,B));check(m.activePokemonView(B).damage()==20,"Second player's second own turn");}
