    static void counterOrderAndRetention(){var m=game();UUID source=active(m,A);var energy=hand(m,A,"psychic");attach(m,A,"psychic");var tool=hand(m,A,"tool");m.playTrainer(A,tool.instanceId(),source);m.placeDamageCountersByEffect(A,A,source,6);m.applySpecialConditionByEffect(A,A,SpecialCondition.POISONED);int start=m.replayTranscript().size();var rng=m.randomTranscript();ability(m,A,source);var v=m.activePokemonView(A);check(v.pokemonId().equals(source)&&v.topCardId().equals(TREE)&&v.hitPoints()==130&&v.damage()==80&&v.conditions().isEmpty()&&v.attachedEnergyIds().contains(energy.instanceId())&&v.attachedTools().stream().anyMatch(c->c.instanceId().equals(tool.instanceId()))&&!m.privateView(A).discard().contains(energy)&&m.phase()==MatchPhase.TURN,"Evolution did not preserve identity/damage/attachments, cure conditions, or complete self counters after evolution");var ops=m.replayTranscript().subList(start,m.replayTranscript().size()).stream().map(vv->vv.operation()).toList();int evolve=ops.indexOf("已审核效果使宝可梦进化"),counters=ops.indexOf("已审核效果放置伤害指示物");check(evolve>=0&&counters>evolve&&m.randomTranscript().equals(rng),"Actual evolution must precede counter operation without RNG");}
